    cart {
      shipping_addresses {
        selected_shipping_method {
          amount {
            currency
            value
          }
          price_excl_tax {
            currency
            value
          }
          price_incl_tax {
            currency
            value
          }
        }
        available_shipping_methods{
          amount {
            currency
            value
          }
          price_excl_tax {
            currency
            value
          }
          price_incl_tax {
            currency
            value
          }
